-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["9a48d7c0679d3b3f"] = { "Gli ⟦Highborne=Alti Nobili⟧, o Quel'dorei, come Azshara li aveva chiamati in ere lontane, avrebbero infine toccato terra nel paese orientale che gli uomini avrebbero chiamato Lordaeron. Progettavano di costruire un proprio regno magico, Quel'Thalas, e di rinnegare i precetti degli elfi della notte, il culto della luna e la vita notturna. Da allora in poi avrebbero abbracciato il sole e sarebbero stati conosciuti solo come alti elfi.", "." },
  ["9a4b17fb05aac4d9"] = { "La magia ha quattro regole:\n\nLa magia è potente.\n\nLa magia corrompe.\n\nLa magia crea dipendenza.\n\nLa magia attira gli abitanti della ⟦Twisting Nether=Distorsione Fatua⟧ verso chi maneggia l'arcano.\n\nSu queste regole puoi sempre contare. Queste regole governeranno il tuo destino se sceglierai di proseguire sulla via del mago.\n\nSe hai la stoltezza di ignorare questo avvertimento, vieni a parlarmi nell'ala della biblioteca dell'abbazia della ⟦Northshire=Contea del Nord⟧. Ti aspetterò al piano di sopra.\n\n-Khelden Bremen, istruttore dei maghi", "." },
  ["9a57ef9877729204"] = { "Col passare del tempo, Quel'Thalas divenne uno splendido monumento agli sforzi e all'abilità magica degli alti elfi. I suoi magnifici palazzi erano costruiti nello stesso stile architettonico delle antiche sale di Kalimdor, ma si intrecciavano con la conformazione naturale del territorio. Quel'Thalas era diventata lo splendido gioiello che gli elfi avevano tanto desiderato creare.", "." },
  ["9a6922aa215756af"] = { "Helgrum,\n\ni miei complimenti a chiunque abbia dato l'ordine di stabilire la nostra base di Kargath nelle ⟦Badlands=Maleterre⟧. È il luogo ideale per addestrare le nostre truppe. Il clima ostile, la fauna feroce, gli indigeni bellicosi e la totale assenza di sostegno dall'esterno ne fanno un crogiolo dal quale usciranno soltanto i migliori guerrieri ed esploratori.\n\nOttima pianificazione. Ben fatto.", "." },
  ["9a9efd5c80387bf5"] = { "Alla fine Arthas immerse i resti di Kel'Thuzad nelle acque sacre del Pozzo Solare. Benché questo gesto contaminasse le potenti acque dell'Eternità, Kel'Thuzad rinacque come lich stregone. Risorto come un essere molto più potente, Kel'Thuzad spiegò la fase successiva del piano del Re dei Lich.", "." },
  ["9aa6dc075ffc2004"] = { "Mi sono trovato davanti a un Infernale torreggiante sul campo di battaglia, con l'esercito della Legione Infuocata che avanzava da ogni direzione. Una banda indisciplinata di troll mi sembra innocua quanto una lepre sulle colline di Dun Morogh.\n\nSuperammo le ⟦Tkashi Ruins=Rovine di Tkashi⟧ senza incidenti, con grande sollievo di Barnil. Il gruppo proseguì verso ovest, in direzione del Grande Mare, costeggiando le ⟦Ruins of Zul'Kunda=Rovine di Zul'Kunda⟧ appena a sud. Mentre risalivamo le alte scogliere sul mare avvistammo il nostro primo raptor.", "." },
  ["9ad192791a7d99ab"] = { "E quando ciò sarà fatto, potrà cominciare la fase successiva del nostro piano. Con una nazione tutta nostra e una base di potere in questa regione, potremo preparare la strada al Third Host.\n\nPresto i Signori della Legione ricompenseranno le nostre opere facendo piovere di nuovo fuoco dai cieli!", "." },
})
